package hu.Taliann.iceSMP.commands;

import hu.Taliann.iceSMP.data.FactionType;
import hu.Taliann.iceSMP.managers.CurrencyManager;
import hu.Taliann.iceSMP.utils.TextUtil;
import io.papermc.paper.command.brigadier.BasicCommand;
import io.papermc.paper.command.brigadier.CommandSourceStack;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import org.jspecify.annotations.NonNull;

import java.util.Collection;
import java.util.List;
import java.util.stream.Stream;

public final class BankCommand implements BasicCommand {

    private final CurrencyManager currencyManager;

    public BankCommand(final CurrencyManager currencyManager) {
        this.currencyManager = currencyManager;
    }

    @Override
    public void execute(final @NonNull CommandSourceStack commandSourceStack, final @NonNull String[] args) {
        final CommandSender sender = commandSourceStack.getSender();

        if (args.length == 0) {
            sendHelp(sender);
            return;
        }

        final String subcommand = args[0].toLowerCase();
        switch (subcommand) {
            case "balance" -> handleBalance(sender);
            case "deposit" -> handleDeposit(sender);
            case "withdraw" -> handleWithdraw(sender, args);
            default -> {
                sender.sendMessage(TextUtil.color("&cIsmeretlen alparancs: &f" + args[0]));
                sendHelp(sender);
            }
        }
    }

    @Override
    public @NonNull Collection<String> suggest(final @NonNull CommandSourceStack commandSourceStack, final @NonNull String[] args) {
        if (args.length == 1) {
            return Stream.of("balance", "deposit", "withdraw")
                    .filter(name -> name.startsWith(args[0].toLowerCase()))
                    .toList();
        }

        if (args.length == 2 && "withdraw".equalsIgnoreCase(args[0])) {
            final String prefix = args[1].toLowerCase();
            return Stream.of("red", "blue", "neutral")
                    .filter(name -> name.startsWith(prefix))
                    .toList();
        }

        return List.of();
    }

    private void handleBalance(final CommandSender sender) {
        if (!(sender instanceof Player player)) {
            sender.sendMessage(TextUtil.color("&cEzt a parancsot csak játékos használhatja."));
            return;
        }

        sender.sendMessage(TextUtil.color("&6Egyenlegeid: &e" + currencyManager.describeBalances(player)));
    }

    private void handleDeposit(final CommandSender sender) {
        if (!(sender instanceof Player player)) {
            sender.sendMessage(TextUtil.color("&cEzt a parancsot csak játékos használhatja."));
            return;
        }

        final double deposited = currencyManager.deposit(player);
        if (deposited <= 0.0D) {
            sender.sendMessage(TextUtil.color("&eNem találtam beváltható valuta itemet a készletedben."));
            return;
        }

        sender.sendMessage(TextUtil.color("&aSikeres beváltás: &f" + currencyManager.formatBalance(deposited) + " &avaluta került a bankba."));
    }

    private void handleWithdraw(final CommandSender sender, final String[] args) {
        if (!(sender instanceof Player player)) {
            sender.sendMessage(TextUtil.color("&cEzt a parancsot csak játékos használhatja."));
            return;
        }

        if (args.length < 3) {
            sender.sendMessage(TextUtil.color("&cHasználat: /bank withdraw <red|blue|neutral> <amount>"));
            return;
        }

        final FactionType currencyType = FactionType.fromInput(args[1]);
        if (currencyType == null) {
            sender.sendMessage(TextUtil.color("&cIsmeretlen valuta."));
            return;
        }

        final int amount;
        try {
            amount = Integer.parseInt(args[2]);
        } catch (final NumberFormatException exception) {
            sender.sendMessage(TextUtil.color("&cÉrvénytelen összeg."));
            return;
        }

        if (amount <= 0) {
            sender.sendMessage(TextUtil.color("&cAz összegnek pozitívnak kell lennie."));
            return;
        }

        if (!currencyManager.withdraw(player, currencyType, amount)) {
            sender.sendMessage(TextUtil.color("&cNincs elég bankegyenleged ehhez."));
            return;
        }

        sender.sendMessage(TextUtil.color("&aSikeres kivétel: &e" + currencyManager.formatBalance(amount) + " &f" + currencyType.getDisplayName() + " &avaluta vissza lett adva itemként."));
    }

    private void sendHelp(final CommandSender sender) {
        sender.sendMessage(TextUtil.color("&6/bank &7- elérhető parancsok:"));
        sender.sendMessage(TextUtil.color("&e/bank balance &7- megmutatja az összes egyenleget."));
        sender.sendMessage(TextUtil.color("&e/bank deposit &7- beváltja a fizikai valuta itemeket."));
        sender.sendMessage(TextUtil.color("&e/bank withdraw <red|blue|neutral> <amount> &7- fizikai valutát ad vissza."));
    }
}

package hu.Taliann.iceSMP.commands;

import hu.Taliann.iceSMP.data.FactionType;
import hu.Taliann.iceSMP.managers.CurrencyManager;
import hu.Taliann.iceSMP.utils.MessageManager;
import hu.Taliann.iceSMP.utils.TextUtil;
import io.papermc.paper.command.brigadier.BasicCommand;
import io.papermc.paper.command.brigadier.CommandSourceStack;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import org.jspecify.annotations.NonNull;

import java.util.Collection;
import java.util.List;
import java.util.stream.Stream;

public final class BankCommand implements BasicCommand {

    private final CurrencyManager currencyManager;
    private final MessageManager messageManager;

    public BankCommand(final CurrencyManager currencyManager, final MessageManager messageManager) {
        this.currencyManager = currencyManager;
        this.messageManager = messageManager;
    }

    @Override
    public void execute(final @NonNull CommandSourceStack commandSourceStack, final @NonNull String[] args) {
        final CommandSender sender = commandSourceStack.getSender();

        if (args.length == 0) {
            sendHelp(sender);
            return;
        }

        final String subcommand = args[0].toLowerCase();
        switch (subcommand) {
            case "balance" -> handleBalance(sender);
            case "deposit" -> handleDeposit(sender);
            case "withdraw" -> handleWithdraw(sender, args);
            default -> {
                sender.sendMessage(TextUtil.color(messageManager.get("messages.bank-unknown-subcommand", "&cIsmeretlen alparancs: &f%s", args[0])));
                sendHelp(sender);
            }
        }
    }

    @Override
    public @NonNull Collection<String> suggest(final @NonNull CommandSourceStack commandSourceStack, final @NonNull String[] args) {
        if (args.length == 1) {
            return Stream.of("balance", "deposit", "withdraw")
                    .filter(name -> name.startsWith(args[0].toLowerCase()))
                    .toList();
        }

        if (args.length == 2 && "withdraw".equalsIgnoreCase(args[0])) {
            final String prefix = args[1].toLowerCase();
            return Stream.of("red", "blue", "neutral")
                    .filter(name -> name.startsWith(prefix))
                    .toList();
        }

        return List.of();
    }

    private void handleBalance(final CommandSender sender) {
        if (!(sender instanceof Player player)) {
            sender.sendMessage(TextUtil.color(messageManager.get("messages.player-only", "&cEzt a parancsot csak játékos használhatja.")));
            return;
        }

        sender.sendMessage(TextUtil.color("&6Egyenlegeid: &e" + currencyManager.describeBalances(player)));
    }

    private void handleDeposit(final CommandSender sender) {
        if (!(sender instanceof Player player)) {
            sender.sendMessage(TextUtil.color(messageManager.get("messages.player-only", "&cEzt a parancsot csak játékos használhatja.")));
            return;
        }

        final double deposited = currencyManager.deposit(player);
        if (deposited <= 0.0D) {
            sender.sendMessage(TextUtil.color(messageManager.get("messages.bank-no-currency-items", "&eNem találtam beváltható valuta itemet a készletedben.")));
            return;
        }

        sender.sendMessage(TextUtil.color(messageManager.get("messages.bank-deposit-success", "&aSikeres beváltás: &f%s &avaluta került a bankba.", currencyManager.formatBalance(deposited))));
    }

    private void handleWithdraw(final CommandSender sender, final String[] args) {
        if (!(sender instanceof Player player)) {
            sender.sendMessage(TextUtil.color(messageManager.get("messages.player-only", "&cEzt a parancsot csak játékos használhatja.")));
            return;
        }

        if (args.length < 3) {
            sender.sendMessage(TextUtil.color(messageManager.get("messages.bank-withdraw-usage", "&cHasználat: /bank withdraw <red|blue|neutral> <amount>")));
            return;
        }

        final FactionType currencyType = FactionType.fromInput(args[1]);
        if (currencyType == null) {
            sender.sendMessage(TextUtil.color(messageManager.get("messages.bank-unknown-currency", "&cIsmeretlen valuta.")));
            return;
        }

        final int amount;
        try {
            amount = Integer.parseInt(args[2]);
        } catch (final NumberFormatException exception) {
            sender.sendMessage(TextUtil.color(messageManager.get("messages.invalid-amount", "&cÉrvénytelen összeg.")));
            return;
        }

        if (amount <= 0) {
            sender.sendMessage(TextUtil.color(messageManager.get("messages.amount-must-be-positive", "&cAz összegnek pozitívnak kell lennie.")));
            return;
        }

        if (!currencyManager.withdraw(player, currencyType, amount)) {
            sender.sendMessage(TextUtil.color(messageManager.get("messages.bank-insufficient-balance", "&cNincs elég bankegyenleged ehhez.")));
            return;
        }

        sender.sendMessage(TextUtil.color(messageManager.get("messages.bank-withdraw-success", "&aSikeres kivétel: &e%s &f%s &avaluta vissza lett adva itemként.", currencyManager.formatBalance(amount), currencyType.getDisplayName())));
    }

    private void sendHelp(final CommandSender sender) {
        sender.sendMessage(TextUtil.color(messageManager.get("messages.bank-help-header", "&6/bank &7- elérhető parancsok:")));
        sender.sendMessage(TextUtil.color(messageManager.get("messages.bank-help-balance", "&e/bank balance &7- megmutatja az összes egyenleget.")));
        sender.sendMessage(TextUtil.color(messageManager.get("messages.bank-help-deposit", "&e/bank deposit &7- beváltja a fizikai valuta itemeket.")));
        sender.sendMessage(TextUtil.color(messageManager.get("messages.bank-help-withdraw", "&e/bank withdraw <red|blue|neutral> <amount> &7- fizikai valutát ad vissza.")));
    }
}

package hu.Taliann.iceSMP.commands;

import hu.Taliann.iceSMP.commands.currency.CurrencyBalanceSubcommand;
import hu.Taliann.iceSMP.commands.currency.CurrencyExchangeSubcommand;
import hu.Taliann.iceSMP.commands.currency.CurrencyPaySubcommand;
import hu.Taliann.iceSMP.commands.currency.CurrencySetSubcommand;
import hu.Taliann.iceSMP.commands.currency.CurrencySubcommand;
import hu.Taliann.iceSMP.managers.ConfigManager;
import hu.Taliann.iceSMP.managers.CurrencyManager;
import hu.Taliann.iceSMP.utils.TextUtil;
import io.papermc.paper.command.brigadier.BasicCommand;
import io.papermc.paper.command.brigadier.CommandSourceStack;
import org.bukkit.command.CommandSender;
import org.jspecify.annotations.NonNull;

import java.util.Arrays;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public final class CurrencyCommand implements BasicCommand {

    private final Map<String, CurrencySubcommand> subcommands = new LinkedHashMap<>();
    private final ConfigManager configManager;

    public CurrencyCommand(final CurrencyManager currencyManager, final ConfigManager configManager) {
        this.configManager = configManager;
        register(new CurrencyBalanceSubcommand(currencyManager));
        register(new CurrencyPaySubcommand(currencyManager));
        register(new CurrencySetSubcommand(currencyManager));
        register(new CurrencyExchangeSubcommand(currencyManager, configManager));
    }

    private void register(final CurrencySubcommand subcommand) {
        subcommands.put(subcommand.name().toLowerCase(), subcommand);
    }

    @Override
    public void execute(final @NonNull CommandSourceStack commandSourceStack, final @NonNull String[] args) {
        final CommandSender sender = commandSourceStack.getSender();

        if (args.length == 0) {
            sendHelp(sender);
            return;
        }

        final CurrencySubcommand subcommand = subcommands.get(args[0].toLowerCase());
        if (subcommand == null) {
            sender.sendMessage(TextUtil.color("&cIsmeretlen alparancs: &f" + args[0]));
            sendHelp(sender);
            return;
        }

        final String[] subArgs = Arrays.copyOfRange(args, 1, args.length);
        subcommand.execute(sender, subArgs);
    }

    @Override
    public @NonNull Collection<String> suggest(final @NonNull CommandSourceStack commandSourceStack, final @NonNull String[] args) {
        final CommandSender sender = commandSourceStack.getSender();

        if (args.length == 1) {
            return subcommands.keySet().stream()
                    .filter(name -> name.startsWith(args[0].toLowerCase()))
                    .toList();
        }

        final CurrencySubcommand subcommand = subcommands.get(args[0].toLowerCase());
        if (subcommand == null) {
            return List.of();
        }

        final String[] subArgs = Arrays.copyOfRange(args, 1, args.length);
        return subcommand.tabComplete(sender, subArgs);
    }

    private void sendHelp(final CommandSender sender) {
        final String header = TextUtil.color(configManager.getString("messages.currency-help-header", "&6/currency &7- elérhető parancsok:"));
        sender.sendMessage(header);
        for (final CurrencySubcommand subcommand : subcommands.values()) {
            sender.sendMessage(TextUtil.color("&e" + subcommand.usage() + " &7- " + subcommand.description()));
        }
    }
}

