package hu.taliann.icesmp.gui;

import hu.taliann.icesmp.data.FactionType;
import hu.taliann.icesmp.managers.ConfigManager;
import hu.taliann.icesmp.managers.CurrencyManager;
import hu.taliann.icesmp.managers.FactionManager;
import hu.taliann.icesmp.utils.MessageManager;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.serializer.legacy.LegacyComponentSerializer;
import org.bukkit.Location;
import org.bukkit.entity.Display;
import org.bukkit.entity.Player;
import org.bukkit.entity.TextDisplay;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.scheduler.BukkitTask;

import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

public final class ProfileGui {

    private static final LegacyComponentSerializer LEGACY = LegacyComponentSerializer.legacySection();

    private final JavaPlugin plugin;
    private final ConfigManager configManager;
    private final FactionManager factionManager;
    private final CurrencyManager currencyManager;
    private final MessageManager messageManager;
    private final Map<UUID, ProfileHudSession> activeSessions = new ConcurrentHashMap<>();

    public ProfileGui(
            final JavaPlugin plugin,
            final ConfigManager configManager,
            final FactionManager factionManager,
            final CurrencyManager currencyManager,
            final MessageManager messageManager
    ) {
        this.plugin = plugin;
        this.configManager = configManager;
        this.factionManager = factionManager;
        this.currencyManager = currencyManager;
        this.messageManager = messageManager;
    }

    public void open(final Player player) {
        if (player == null) {
            return;
        }

        close(player.getUniqueId());

        if (!configManager.getBoolean("hud.profile.enabled", true)) {
            player.sendMessage(messageManager.get("messages.profile-disabled", "&cA profile HUD jelenleg ki van kapcsolva."));
            return;
        }

        final TextDisplay display = player.getWorld().spawn(player.getLocation(), TextDisplay.class, spawned -> {
            spawned.setPersistent(false);
            spawned.setGravity(false);
            spawned.setBillboard(Display.Billboard.CENTER);
            spawned.setShadowed(true);
            spawned.setText(buildHudText(player));
        });

        isolateForOwner(player, display);

        final ProfileHudSession session = new ProfileHudSession(display);
        activeSessions.put(player.getUniqueId(), session);

        final long updateInterval = Math.max(1L, configManager.getLong("hud.profile.update-interval-ticks", 5L));
        final long lifetime = Math.max(updateInterval, configManager.getLong("hud.profile.lifetime-ticks", 200L));

        session.updateTask = plugin.getServer().getScheduler().runTaskTimer(plugin, () -> {
            if (!player.isOnline()) {
                close(player.getUniqueId());
                return;
            }

            refresh(player, session);
        }, 0L, updateInterval);

        session.expiryTask = plugin.getServer().getScheduler().runTaskLater(plugin, () -> close(player.getUniqueId()), lifetime);
        refresh(player, session);
    }

    public void close(final Player player) {
        if (player == null) {
            return;
        }

        close(player.getUniqueId());
    }

    public void closeAll() {
        for (final UUID uuid : Map.copyOf(activeSessions).keySet()) {
            close(uuid);
        }
    }

    public void close(final UUID uuid) {
        final ProfileHudSession session = activeSessions.remove(uuid);
        if (session == null) {
            return;
        }

        if (session.updateTask != null) {
            session.updateTask.cancel();
        }

        if (session.expiryTask != null) {
            session.expiryTask.cancel();
        }

        if (session.display != null) {
            session.display.remove();
        }
    }

    private void refresh(final Player player, final ProfileHudSession session) {
        if (session.display == null || !player.isOnline()) {
            close(player.getUniqueId());
            return;
        }

        session.display.teleport(resolveDisplayLocation(player));
        session.display.setText(buildHudText(player));
    }

    private void isolateForOwner(final Player owner, final TextDisplay display) {
        owner.showEntity(plugin, display);
        for (final Player viewer : owner.getWorld().getPlayers()) {
            if (!viewer.getUniqueId().equals(owner.getUniqueId())) {
                viewer.hideEntity(plugin, display);
            }
        }
    }

    private Location resolveDisplayLocation(final Player player) {
        final double forwardDistance = Math.max(0.0D, configManager.getDouble("hud.profile.distance", 3.0D));
        final double verticalOffset = configManager.getDouble("hud.profile.height-offset", -0.25D);

        final Location location = player.getEyeLocation().clone();
        location.add(location.getDirection().normalize().multiply(forwardDistance));
        location.add(0.0D, verticalOffset, 0.0D);
        return location;
    }

    private String buildHudText(final Player player) {
        final FactionType factionType = factionManager.getFaction(player.getUniqueId());
        final String redBalance = currencyManager.formatBalance(currencyManager.getBalance(player, FactionType.RED));
        final String blueBalance = currencyManager.formatBalance(currencyManager.getBalance(player, FactionType.BLUE));
        final String neutralBalance = currencyManager.formatBalance(currencyManager.getBalance(player, FactionType.NEUTRAL));

        final Component component = Component.text()
                .append(message("messages.profile-title", "&d&l✦ &fICESMP PROFIL &d&l✦"))
                .append(Component.newline())
                .append(message("messages.profile-hud-divider", "&8&m━━━━━━━━━━━━━━━━━━━━"))
                .append(Component.newline())
                .append(message("messages.profile-hud-name", "&7✎ &fNév: &e%s", player.getName()))
                .append(Component.newline())
                .append(message("messages.profile-hud-faction", "&7⚑ &fFrakció: &f%s", factionType.getDisplayName()))
                .append(Component.newline())
                .append(message("messages.profile-hud-world", "&7☾ &fVilág: &b%s", player.getWorld().getName()))
                .append(Component.newline())
                .append(message("messages.profile-hud-divider", "&8&m━━━━━━━━━━━━━━━━━━━━"))
                .append(Component.newline())
                .append(message("messages.profile-hud-balances", "&7⛃ &fEgyenlegek"))
                .append(Component.newline())
                .append(message("messages.profile-hud-red-balance", "&c▸ Piros: &f%s", redBalance))
                .append(Component.newline())
                .append(message("messages.profile-hud-blue-balance", "&9▸ Kék: &f%s", blueBalance))
                .append(Component.newline())
                .append(message("messages.profile-hud-neutral-balance", "&5▸ Semleges: &f%s", neutralBalance))
                .append(Component.newline())
                .append(message("messages.profile-hud-divider", "&8&m━━━━━━━━━━━━━━━━━━━━"))
                .append(Component.newline())
                .append(message("messages.profile-hud-actions", "&7Bank: &f/bank deposit &8• &f/bank withdraw <type> <amount>"))
                .append(Component.newline())
                .append(message("messages.profile-hud-close-hint", "&8&oFrissítéshez nyisd meg újra a &f/profile &8&oparancsot"))
                .build();

        return LEGACY.serialize(component);
    }

    private Component message(final String key, final String fallback, final Object... args) {
        return LEGACY.deserialize(messageManager.get(key, fallback, args));
    }

    private static final class ProfileHudSession {

        private final TextDisplay display;
        private BukkitTask updateTask;
        private BukkitTask expiryTask;

        private ProfileHudSession(final TextDisplay display) {
            this.display = display;
        }
    }
}

package hu.taliann.icesmp.gui;

import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import net.kyori.adventure.text.format.TextDecoration;
import org.bukkit.Bukkit;
import org.bukkit.Material;
import org.bukkit.entity.Player;
import org.bukkit.inventory.Inventory;
import org.bukkit.inventory.ItemFlag;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.ItemMeta;
import org.bukkit.inventory.meta.SkullMeta;

import java.util.List;

public final class ProfileGUI {

    private static final int SIZE = 27;
    private static final int SLOT_LEFT = 11;
    private static final int SLOT_CENTER = 13;
    private static final int SLOT_RIGHT = 15;
    private static final Component TITLE = Component.text("» Karakterlap «", NamedTextColor.DARK_GRAY);

    private ProfileGUI() {
    }

    public static void openProfile(final Player viewer, final Player target) {
        if (viewer == null) {
            return;
        }

        final Player profileTarget = target == null ? viewer : target;
        final ProfileHolder holder = new ProfileHolder();
        final Inventory inventory = Bukkit.createInventory(holder, SIZE, TITLE);
        holder.setInventory(inventory);

        fillBackground(inventory);
        inventory.setItem(SLOT_CENTER, createHead(profileTarget));
        inventory.setItem(SLOT_LEFT, createBookIcon());
        inventory.setItem(SLOT_RIGHT, createStatsIcon());

        viewer.openInventory(inventory);
    }

    public static void closeAll() {
        for (final Player player : Bukkit.getOnlinePlayers()) {
            if (isProfileInventory(player.getOpenInventory().getTopInventory())) {
                player.closeInventory();
            }
        }
    }

    public static boolean isProfileInventory(final Inventory inventory) {
        return inventory != null && inventory.getHolder() instanceof ProfileHolder;
    }

    private static void fillBackground(final Inventory inventory) {
        final ItemStack filler = createFiller();
        for (int slot = 0; slot < SIZE; slot++) {
            inventory.setItem(slot, filler.clone());
        }
    }

    private static ItemStack createHead(final Player target) {
        final ItemStack itemStack = new ItemStack(Material.PLAYER_HEAD);
        final ItemMeta meta = itemStack.getItemMeta();
        if (meta instanceof SkullMeta skullMeta) {
            skullMeta.setOwningPlayer(target);
            applyDisplay(skullMeta,
                    Component.text("[" + target.getName() + "]", NamedTextColor.GOLD, TextDecoration.BOLD),
                    List.of(
                            Component.text("Aktuális kaszt és szint", NamedTextColor.GRAY),
                            Component.text("Egy gyors áttekintés a karakteredről.", NamedTextColor.DARK_GRAY)
                    ));
            itemStack.setItemMeta(skullMeta);
            return itemStack;
        }

        applyDisplay(meta,
                Component.text("[" + target.getName() + "]", NamedTextColor.GOLD, TextDecoration.BOLD),
                List.of(
                        Component.text("Aktuális kaszt és szint", NamedTextColor.GRAY),
                        Component.text("Egy gyors áttekintés a karakteredről.", NamedTextColor.DARK_GRAY)
                ));
        itemStack.setItemMeta(meta);
        return itemStack;
    }

    private static ItemStack createBookIcon() {
        return createIcon(
                Material.KNOWLEDGE_BOOK,
                Component.text("Varázslatok és Képességek", NamedTextColor.LIGHT_PURPLE),
                List.of(
                        Component.text("Nézd meg a mágikus képességeidet.", NamedTextColor.GRAY),
                        Component.text("Később ide jöhetnek a skill panelek.", NamedTextColor.DARK_GRAY)
                )
        );
    }

    private static ItemStack createStatsIcon() {
        return createIcon(
                Material.GOLD_NUGGET,
                Component.text("Statisztikák", NamedTextColor.YELLOW),
                List.of(
                        Component.text("Gyors összegzés a fontos adataidról.", NamedTextColor.GRAY),
                        Component.text("Később ide jöhetnek a részletes statok.", NamedTextColor.DARK_GRAY)
                )
        );
    }

    private static ItemStack createFiller() {
        final ItemStack itemStack = new ItemStack(Material.BLACK_STAINED_GLASS_PANE);
        final ItemMeta meta = itemStack.getItemMeta();
        meta.displayName(Component.empty());
        meta.lore(List.of());
        meta.addItemFlags(ItemFlag.HIDE_ADDITIONAL_TOOLTIP, ItemFlag.HIDE_ATTRIBUTES);
        itemStack.setItemMeta(meta);
        return itemStack;
    }

    private static ItemStack createIcon(final Material material, final Component name, final List<Component> lore) {
        final ItemStack itemStack = new ItemStack(material);
        final ItemMeta meta = itemStack.getItemMeta();
        applyDisplay(meta, name, lore);
        itemStack.setItemMeta(meta);
        return itemStack;
    }

    private static void applyDisplay(final ItemMeta meta, final Component name, final List<Component> lore) {
        meta.displayName(name);
        meta.lore(lore);
        meta.addItemFlags(ItemFlag.HIDE_ADDITIONAL_TOOLTIP, ItemFlag.HIDE_ATTRIBUTES);
    }
}

package hu.taliann.icesmp.listeners;

import hu.taliann.icesmp.gui.ProfileGui;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.player.PlayerQuitEvent;

public final class ProfileGuiListener implements Listener {

    private final ProfileGui profileGui;

    public ProfileGuiListener(final ProfileGui profileGui) {
        this.profileGui = profileGui;
    }

    @EventHandler
    public void onQuit(final PlayerQuitEvent event) {
        profileGui.close(event.getPlayer());
    }
}

package hu.taliann.icesmp.listeners;

import hu.taliann.icesmp.gui.ProfileHolder;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.inventory.InventoryClickEvent;
import org.bukkit.event.inventory.InventoryDragEvent;

public final class ProfileGUIListener implements Listener {

    @EventHandler(ignoreCancelled = true)
    public void onInventoryClick(final InventoryClickEvent event) {
        if (event.getInventory().getHolder() instanceof ProfileHolder) {
            event.setCancelled(true);
        }
    }

    @EventHandler(ignoreCancelled = true)
    public void onInventoryDrag(final InventoryDragEvent event) {
        if (event.getInventory().getHolder() instanceof ProfileHolder) {
            event.setCancelled(true);
        }
    }
}
